import{_ as t,a,b as r,c as i,d as o,e as s,f as n,g as l}from"./chunks/dark-detail.DAFPwsOs.js";import{_ as d,o as c,c as p,a2 as h}from"./chunks/framework.DDY-poMm.js";const w=JSON.parse('{"title":"BTX Wallet (Web3 wallet)","description":"","frontmatter":{},"headers":[],"relativePath":"app/wallet.md","filePath":"app/wallet.md","lastUpdated":1791353800000}'),g={name:"app/wallet.md"};function f(u,e,m,b,x,y){return c(),p("div",null,[...e[0]||(e[0]=[h('<h1 id="btx-wallet-web3-wallet" tabindex="-1">BTX Wallet (Web3 wallet) <a class="header-anchor" href="#btx-wallet-web3-wallet" aria-label="Permalink to &quot;BTX Wallet (Web3 wallet)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Private beta</p><p>BTX Wallet is currently in private beta. To learn more or try it, please <a href="/CoinExchange/contact/">contact us</a>.</p></div><p>BTX Wallet is a <strong>self-custody Web3 wallet</strong>: users buy and sell <strong>xStocks tokenized US stocks and ETFs</strong> on-chain directly with USDC / USDT, and their assets always stay in their own on-chain address.</p><p>The question users ask most is &quot;which broker is behind this, and where are my shares?&quot; In BTX Wallet every trade and every holding is recorded on the blockchain, so users can verify them themselves on a block explorer.</p><h2 id="how-it-differs-from-the-exchange-app" tabindex="-1">How it differs from the exchange app <a class="header-anchor" href="#how-it-differs-from-the-exchange-app" aria-label="Permalink to &quot;How it differs from the exchange app&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Exchange app</th><th>BTX Wallet</th></tr></thead><tbody><tr><td>Who holds the assets</td><td>The platform</td><td><strong>The user</strong> (private keys never leave the user&#39;s phone)</td></tr><tr><td>Account registration</td><td>Required</td><td><strong>Not required</strong>: create or import a wallet and start</td></tr><tr><td>Where trades happen</td><td>Platform matching</td><td><strong>On-chain</strong>, verifiable on a block explorer</td></tr><tr><td>US stock holdings</td><td>Platform ledger</td><td><strong>Tokenized stocks</strong> (xStocks), backed 1:1 by shares held by the issuer</td></tr></tbody></table><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="self-custody-the-platform-never-touches-private-keys" tabindex="-1">Self-custody; the platform never touches private keys <a class="header-anchor" href="#self-custody-the-platform-never-touches-private-keys" aria-label="Permalink to &quot;Self-custody; the platform never touches private keys&quot;">​</a></h3><p>The recovery phrase is stored only on the user&#39;s phone and encrypted by the device&#39;s secure chip; no private key exists on our servers. Face ID is supported, and repeated wrong passcodes trigger progressively longer lockouts. One app can manage several wallets and import existing private keys.</p><h3 id="trade-tokenized-us-stocks-on-chain" tabindex="-1">Trade tokenized US stocks on-chain <a class="header-anchor" href="#trade-tokenized-us-stocks-on-chain" aria-label="Permalink to &quot;Trade tokenized US stocks on-chain&quot;">​</a></h3><p>Buy and sell xStocks US stocks and ETFs directly with USDC / USDT, with price, slippage and fees shown before ordering. Before signing, the app checks exactly how the trade will change balances and approvals, and stops if anything looks wrong; high slippage triggers a warning and a second confirmation. On-chain trading remains available while the US market is closed, with a clear notice that on-chain prices may deviate.</p><h3 id="professional-market-data" tabindex="-1">Professional market data <a class="header-anchor" href="#professional-market-data" aria-label="Permalink to &quot;Professional market data&quot;">​</a></h3><p>Charts from 15 minutes, 1 hour and 4 hours to daily and weekly, with moving averages, volume and a crosshair; drag and pinch to zoom. Below the chart, the order-flow panel shows 24-hour buy/sell counts and live trades. When the US market is closed, the last close time (ET) is shown.</p><h3 id="company-profiles" tabindex="-1">Company profiles <a class="header-anchor" href="#company-profiles" aria-label="Permalink to &quot;Company profiles&quot;">​</a></h3><p>Every stock has a bilingual company profile: company, ticker, industry, type, listing date, exchange, website and description. Profiles are compiled from public information, and websites are only taken from official registrations or verifiable sources.</p><h3 id="news-and-filings" tabindex="-1">News and filings <a class="header-anchor" href="#news-and-filings" aria-label="Permalink to &quot;News and filings&quot;">​</a></h3><p>AI turns public reports into bilingual articles with images. Before publishing, dates and amounts are cross-checked between the two languages, and inconsistent articles are not published. Official company filings from the US SEC are included.</p><h3 id="crypto-quotes" tabindex="-1">Crypto quotes <a class="header-anchor" href="#crypto-quotes" aria-label="Permalink to &quot;Crypto quotes&quot;">​</a></h3><p>The market tab is split into &quot;Stocks | Crypto&quot;. Major coins are quoted from leading exchanges&#39; spot markets, and platform coin prices match our platform. Crypto is view-only and cannot be traded in the wallet.</p><h3 id="appearance-and-language" tabindex="-1">Appearance and language <a class="header-anchor" href="#appearance-and-language" aria-label="Permalink to &quot;Appearance and language&quot;">​</a></h3><p>Light / dark appearance and English / Chinese, following the system or set manually.</p><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+t+'" alt="Home" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Home</b><br>Price cards, quick actions and today’s top movers </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="Market · Stocks" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Market · Stocks</b><br>Listed tokenized US stocks and ETFs with 7-day trends </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+r+'" alt="Market · Crypto" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Market · Crypto</b><br>Major coins and platform coin, view-only </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+i+'" alt="Chart" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Chart</b><br>15-minute to weekly candles with MAs, volume and crosshair </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+o+'" alt="Order flow" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Order flow</b><br>24-hour buy/sell split and live trades </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+s+'" alt="Company profile" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Company profile</b><br>Company, industry, listing date, exchange and website </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+n+'" alt="News" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>News</b><br>AI-curated bilingual articles </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+l+'" alt="Dark mode" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Dark mode</b><br>Switch between light and dark </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">About these screenshots</p><p>These are simulator captures of the beta build (Chinese interface); prices and news come from the test environment.</p></div><h2 id="operator-console" tabindex="-1">Operator console <a class="header-anchor" href="#operator-console" aria-label="Permalink to &quot;Operator console&quot;">​</a></h2><p>Managed from the &quot;Web3 Wallet&quot; menu in the operator console:</p><ul><li><strong>Wallet tokens</strong>: sync from the issuer&#39;s official list, choose which stocks to list and their order</li><li><strong>Swap records and statistics</strong>: every trade, volume and platform service fees</li><li><strong>Wallet users</strong>: created or imported wallet addresses and their activity</li><li><strong>Wallet news / token profiles</strong>: view, edit, take down, or regenerate</li><li><strong>Wallet settings</strong>: platform service fee, payment coins, news update frequency, crypto list</li></ul><h2 id="safety-notes" tabindex="-1">Safety notes <a class="header-anchor" href="#safety-notes" aria-label="Permalink to &quot;Safety notes&quot;">​</a></h2><ul><li>The platform does not store private keys. <strong>A lost recovery phrase cannot be recovered</strong>, so keep an offline backup.</li><li>Tokenized stocks are issued by the issuer. Holders have no shareholder voting rights, and the issuer may pause transfers in certain cases.</li><li>Confirmed on-chain transactions cannot be reversed.</li></ul><p>BTX Wallet is included in the FDE Launch Partner package, with full source code for the wallet app and its console. See <a href="/CoinExchange/intro/pricing">Pricing &amp; Packages</a>.</p>',30)])])}const q=d(g,[["render",f]]);export{w as __pageData,q as default};
